const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (input) => {
    const aa = parseInt(input.trim(), 10);
    let k, l, ttl = 0;

    for (let i = 2; i < aa; i++) {
        k = aa;
        while (k > 0) {
            ttl += (k % i);
            k = Math.floor(k / i);
            if (k < i) {
                ttl += k;
                break;
            }
        }
    }

    l = aa - 2;
    for (let i = l; i > 1; i--) {
        if (ttl % i === 0 && l % i === 0) {
            ttl /= i;
            l /= i;
            break;
        }
    }

    console.log(`${ttl}/${l}`);
    rl.close();
});

